    },
	mounted() {
		if(this.$route.query.pageFlag=='register'){
			this.tableName = this.$route.query.role;
			if(this.tableName=='huiyuan'){
				this.registerForm = {
					yonghuzhanghao: '',
					xingming: '',
					mima: '',
					mima2: '',
					xingbie: '',
					shouji: '',
					touxiang: '',
				}
			}
			if(this.tableName=='yuangong'){
				this.registerForm = {
					yuangongzhanghao: '',
					yuangongxingming: '',
					mima: '',
					mima2: '',
					xingbie: '',
					lianxidianhua: '',
					jiatingzhuzhi: '',
					touxiang: '',
				}
			}
			if ('huiyuan' == this.tableName) {
				this.requiredRules.yonghuzhanghao = [{ required: true, message: '请输入用户账号', trigger: 'blur' }]
			}
			if ('huiyuan' == this.tableName) {
				this.requiredRules.xingming = [{ required: true, message: '请输入姓名', trigger: 'blur' }]
			}
			if ('huiyuan' == this.tableName) {
				this.requiredRules.mima = [{ required: true, message: '请输入密码', trigger: 'blur' }]
			}
			if ('yuangong' == this.tableName) {
				this.requiredRules.yuangongzhanghao = [{ required: true, message: '请输入员工账号', trigger: 'blur' }]
			}
			if ('yuangong' == this.tableName) {
				this.requiredRules.yuangongxingming = [{ required: true, message: '请输入员工姓名', trigger: 'blur' }]
			}
			if ('yuangong' == this.tableName) {
				this.requiredRules.mima = [{ required: true, message: '请输入密码', trigger: 'blur' }]
			}
		}
	},
    created() {
		this.pageFlag = this.$route.query.pageFlag;
		if(this.$route.query.pageFlag=='register'){
		  if ('huiyuan' == this.tableName) {
			this.rules.yonghuzhanghao = [{ required: true, message: '请输入用户账号', trigger: 'blur' }];
		  }
		  if ('huiyuan' == this.tableName) {
			this.rules.xingming = [{ required: true, message: '请输入姓名', trigger: 'blur' }];
		  }
		  if ('huiyuan' == this.tableName) {
			this.rules.mima = [{ required: true, message: '请输入密码', trigger: 'blur' }];
		  }
			this.huiyuanxingbieOptions = "男,女".split(',');
		  if ('huiyuan' == this.tableName) {
			this.rules.shouji = [{ required: true, validator: this.$validate.isMobile, trigger: 'blur' }];
		  }
		  if ('yuangong' == this.tableName) {
			this.rules.yuangongzhanghao = [{ required: true, message: '请输入员工账号', trigger: 'blur' }];
		  }
		  if ('yuangong' == this.tableName) {
			this.rules.yuangongxingming = [{ required: true, message: '请输入员工姓名', trigger: 'blur' }];
		  }
		  if ('yuangong' == this.tableName) {
			this.rules.mima = [{ required: true, message: '请输入密码', trigger: 'blur' }];
		  }
			this.yuangongxingbieOptions = "男,女".split(',');
		  if ('yuangong' == this.tableName) {
			this.rules.lianxidianhua = [{ required: true, validator: this.$validate.isMobile, trigger: 'blur' }];
		  }
		}
    },
    //方法集合
    methods: {
		changeRules(name){
			if(this.requiredRules[name]){
				return true
			}
			return false
		},
      // 获取uuid
      getUUID () {
        return new Date().getTime();
      },
        // 下二随
      huiyuantouxiangUploadChange(fileUrls) {
          this.registerForm.touxiang = fileUrls.replace(new RegExp(this.$config.baseUrl,"g"),"");
      },
      yuangongtouxiangUploadChange(fileUrls) {
          this.registerForm.touxiang = fileUrls.replace(new RegExp(this.$config.baseUrl,"g"),"");
      },

        // 多级联动参数


      submitForm(formName) {
        this.$refs[formName].validate((valid) => {
          if (valid) {
            var url=this.tableName+"/register";
				if((!this.registerForm.yonghuzhanghao) && `huiyuan` == this.tableName){
					this.$message.error(`用户账号不能为空`);
					return
				}
				if((!this.registerForm.xingming) && `huiyuan` == this.tableName){
					this.$message.error(`姓名不能为空`);
					return
				}
               if(`huiyuan` == this.tableName && this.registerForm.mima!=this.registerForm.mima2) {
                this.$message.error(`两次密码输入不一致`);
                return
               }
				if((!this.registerForm.mima) && `huiyuan` == this.tableName){
					this.$message.error(`密码不能为空`);
					return
				}
					if(`huiyuan` == this.tableName && this.registerForm.shouji &&(!this.$validate.isMobile2(this.registerForm.shouji))){
						this.$message.error(`手机应输入手机格式`);
						return
					}
				if((!this.registerForm.yuangongzhanghao) && `yuangong` == this.tableName){
					this.$message.error(`员工账号不能为空`);
					return
				}
				if((!this.registerForm.yuangongxingming) && `yuangong` == this.tableName){
					this.$message.error(`员工姓名不能为空`);
					return
				}
               if(`yuangong` == this.tableName && this.registerForm.mima!=this.registerForm.mima2) {
                this.$message.error(`两次密码输入不一致`);
                return
               }
				if((!this.registerForm.mima) && `yuangong` == this.tableName){
					this.$message.error(`密码不能为空`);
					return
				}
					if(`yuangong` == this.tableName && this.registerForm.lianxidianhua &&(!this.$validate.isMobile2(this.registerForm.lianxidianhua))){
						this.$message.error(`联系电话应输入手机格式`);
						return
					}
            this.$http.post(url, this.registerForm).then(res => {
              if (res.data.code === 0) {
                this.$message({
                  message: '注册成功',
                  type: 'success',
                  duration: 1500,
                  onClose: () => {
                    this.$router.push('/login');
                  }
                });
              } else {
                this.$message.error(res.data.msg);
              }
            });
          } else {
            return false;
          }
        });
      },
      resetForm(formName) {
        this.$refs[formName].resetFields();
      }
